import type { Metadata } from 'next'
import localFont from 'next/font/local'
import Navigation from '@/components/marketing/Navigation'
import './globals.css'

// Load custom fonts
const supernova = localFont({
  src: '../public/fonts/Supernova - Personal Used.ttf',
  variable: '--font-supernova',
  display: 'swap',
})

const arpDisplay = localFont({
  src: '../public/fonts/ARPDisplay-240.ttf',
  variable: '--font-arp-display',
  display: 'swap',
})

export const metadata: Metadata = {
  title: 'dAItaniverse - All-in-One Platform for ADHD Entrepreneurs',
  description: 'AI Coaching + Project Management + Quiz Builder + CRM + Email Marketing. No BS. Just Results. £26/month.',
}

export default function RootLayout({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <html lang="en" className={`${supernova.variable} ${arpDisplay.variable}`}>
      <body>
        <Navigation />
        {children}
      </body>
    </html>
  )
}
